(() => {
  const W=window.ZoneRPGWorld,I=window.ZoneRPGItems,S=window.ZoneRPGState,X=window.ZoneRPGExpedition;
  let state=S.fresh(),listeners=new Set(),deferEmission=0;
  const clone=x=>JSON.parse(JSON.stringify(x)),clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n)),rand=a=>a[Math.floor(Math.random()*a.length)];
  const emit=()=>{X.project(state);if(state.expedition.active)state.expedition.currentEncounterId=state.event?.id||null;if(!deferEmission)listeners.forEach(fn=>fn());};
  function log(text){state.log.push(text);state.log=state.log.slice(-10);}
  function notify(text){log(text);emit();}
  function count(id){return state.inventory.filter(x=>x.id===id).reduce((n,x)=>n+x.qty,0);}
  function needDrain(amount){return Math.max(.4,amount*(1-Math.max(0,(state.attributes?.endurance||2)-2)*.035));}
  function findItem(ref){return state.inventory.find(x=>x.instanceId===ref)||state.inventory.find(x=>x.id===ref)||null;}
  function removeItem(ref,qty=1){const row=state.inventory.find(x=>x.instanceId===ref)||state.inventory.find(x=>x.id===ref);if(!row||row.qty<qty)return false;if(row.instanceId){state.inventory=state.inventory.filter(x=>x!==row);for(const slot of ['primary','sidearm','melee','armor','head','backpack','detector'])if(state.equipment[slot]===row.instanceId)state.equipment[slot]=null;state.equipment.artifacts=state.equipment.artifacts.filter(id=>id!==row.instanceId);if(!itemForSlot(state.equipment.activeWeaponSlot))state.equipment.activeWeaponSlot=['sidearm','primary','melee'].find(slot=>itemForSlot(slot))||'melee';syncWeaponAlias();state.player.health=Math.min(state.player.health,finalStats().maxHealth);state.player.stamina=Math.min(state.player.stamina,finalStats().maxStamina);return true;}return remove(row.id,qty);}
  function isEquipped(ref){return ['primary','sidearm','melee','armor','head','backpack','detector'].some(slot=>state.equipment[slot]===ref)||state.equipment.artifacts.includes(ref);}
  function itemForSlot(slot){const ref=state.equipment[slot];return ref?findItem(ref):null;}
  function weaponItem(){return itemForSlot(state.equipment.activeWeaponSlot)||itemForSlot('sidearm')||itemForSlot('primary')||itemForSlot('melee');}
  function activeWeaponState(){const row=weaponItem(),item=I.items[row?.id],weapon=I.weapons[item?.weaponId];return weapon?{id:row.id,instanceId:row.instanceId||row.id,item,weapon,magazine:state.magazines[row.id]||0,reserve:weapon.ammoType?count(weapon.ammoType):0}:null;}
  function syncWeaponAlias(){state.equipment.weapon=weaponItem()?.id||'';}
  function environment(){return W.locations[state.travelTo||state.player.location]||W.locations[state.player.location];}
  function weight(){return state.inventory.reduce((a,x)=>a+(I.items[x.id]?.weight||0)*x.qty,0);}
  function passive(){const out={protection:0,radResist:0,maxWeight:0,maxHealth:0,maxStamina:0,radPerTrip:0,accuracy:0,critChance:0,evasion:0,healthRegen:0,artifactFindChance:0};const refs=['primary','sidearm','melee','armor','head','backpack','detector'].map(slot=>state.equipment[slot]).concat(state.equipment.artifacts);for(const ref of refs){const row=findItem(ref),fx=I.items[row?.id]?.effect||{};for(const [key,value]of Object.entries(fx))if(Number.isFinite(Number(value)))out[key]=(out[key]||0)+Number(value);}for(const [key,value]of Object.entries(state.temporaryModifiers||{}))if(Number.isFinite(Number(value)))out[key]=(out[key]||0)+Number(value);return out;}
  function finalStats(){const p=state.player,mods=passive(),base=state.baseStats||{maxHealth:p.maxHealth,maxStamina:p.maxStamina,maxCarryWeight:25},a=state.attributes||{};return{...mods,maxHealth:Math.max(1,base.maxHealth+(mods.maxHealth||0)+((a.endurance||2)-2)*2),maxStamina:Math.max(1,base.maxStamina+(mods.maxStamina||0)+((a.endurance||2)-2)*2),maxCarryWeight:Math.max(1,base.maxCarryWeight+(mods.maxWeight||0)+((a.strength||2)-2)*1.25),accuracy:(mods.accuracy||0)+Math.max(0,(a.agility||2)-2)*.006,evasion:(mods.evasion||0)+Math.max(0,(a.agility||2)-2)*.006,artifactFindChance:(mods.artifactFindChance||0)+Math.max(0,(a.perception||2)-2)*.008,dialogueBonus:Math.max(0,(a.intelligence||2)-2)*2};}
  function xpForNextLevel(level=state.player.rank){return 120+Math.max(0,level-1)*75;}
  function grantXP(amount,source='') {if(state.expedition.active)state.expedition.summary.xp+=Math.max(0,Math.floor(amount));const p=state.player;p.xp=Math.max(0,p.xp+Math.max(0,Math.floor(amount)));let gained=0;while(p.xp>=xpForNextLevel(p.rank)){p.xp-=xpForNextLevel(p.rank);p.rank++;state.attributePoints=(state.attributePoints||0)+2;gained++;}if(gained){notify(`НОВЫЙ УРОВЕНЬ · ${p.rank} · +${gained*2} очка характеристик${source?` (${source})`:''}.`);document.body.classList.add('level-up');setTimeout(()=>document.body.classList.remove('level-up'),900);}else if(amount>0)log(`+${amount} опыта${source?` · ${source}`:''}.`);}
  const masteryKey=weapon=>weapon?.weaponClass==='melee'?'melee':weapon?.weaponClass==='shotgun'?'shotguns':weapon?.weaponClass==='pistol'?'pistols':weapon?.weaponClass==='smg'?'smg':'rifles';
  function improveMastery(weapon){const key=masteryKey(weapon),old=state.weaponMastery[key]||0;state.weaponMastery[key]=Math.min(100,old+0.35);if(Math.floor(state.weaponMastery[key]/10)>Math.floor(old/10))notify(`Навык «${S.MASTERY_NAMES[key]}» повышен: ${Math.floor(state.weaponMastery[key])}/100.`);}
  function investAttribute(key){if(!Object.prototype.hasOwnProperty.call(state.attributes,key)||state.attributePoints<1)return notify('Нет очков или выбрана неизвестная характеристика.');if(state.attributes[key]>=20)return notify('Характеристика достигла предела.');state.attributePoints--;state.attributes[key]++;const after=finalStats();state.player.health=Math.min(state.player.health,after.maxHealth);state.player.stamina=Math.min(state.player.stamina,after.maxStamina);notify(`${S.ATTRIBUTE_INFO[key].name}: ${state.attributes[key]} · потрачено очко развития.`);emit();}
  function capacity(){return finalStats().maxCarryWeight;}
  function add(id,qty=1){if(!I.items[id]||qty<=0)return 0;const item=I.items[id],current=count(id),room=capacity()-weight(),fit=item.weight===0?qty:Math.min(qty,Math.floor((room+1e-7)/item.weight));if(fit<=0)return 0;if(item.stackable&&current){state.inventory.find(x=>x.id===id).qty+=fit;}else if(item.stackable)state.inventory.push({id,qty:fit});else for(let n=0;n<fit;n++)state.inventory.push({id,qty:1,instanceId:`item-${state.nextItemInstance++}`});if(item.type==='artifact'&&!state.discoveredArtifacts.includes(id)){state.discoveredArtifacts.push(id);log('Справочник: обнаружен '+item.name+'.');}if(state.expedition.active)state.expedition.summary.items[id]=(state.expedition.summary.items[id]||0)+fit;return fit;}
  function remove(id,qty=1){if(!I.items[id])return false;const rows=state.inventory.filter(x=>x.id===id);if(rows.reduce((n,x)=>n+x.qty,0)<qty)return false;let left=qty;for(const row of rows){const take=Math.min(row.qty,left);row.qty-=take;left-=take;if(!left)break;}state.inventory=state.inventory.filter(x=>x.qty>0);return true;}
  function shiftRep(faction,amount){if(!faction)return;state.reputation[faction]=clamp((state.reputation[faction]||0)+amount,-100,100);}
  function unlocked(id){if(!W.locations[id])return false;if(id==='chNpp')return state.visited.includes(id)||state.worldFlags.stationOpen;return state.known.includes(id)||W.locations[state.player.location].neighbors.includes(id);}
  function getRoutes(){return W.locations[state.player.location].neighbors.map(id=>({id,...W.locations[id],open:unlocked(id)&&!routeBlocked(state.player.location,id),reason:routeBlocked(state.player.location,id)?'Дорога временно закрыта по сводке КПК':id==='chNpp'&&!state.worldFlags.stationOpen?'Сначала найди данные о станции':null}));}
  function discover(id){if(W.locations[id]&&!state.known.includes(id)){state.known.push(id);notify(`На карте появилась новая отметка: ${W.locations[id].name}.`);}}
  function maybeReveal(){const choices=W.locations[state.player.location].neighbors.filter(id=>!state.known.includes(id));if(choices.length)discover(rand(choices));if(state.player.location==='pripyat'&&state.worldFlags.documentsFound&&!state.worldFlags.stationOpen){state.worldFlags.stationOpen=true;notify('Схема открыла путь к саркофагу ЧАЭС.');}}
  function objectiveProgress(type,target,amount=1){for(const q of state.quests.active){const d=W.quests.find(x=>x.id===q.id);if(!d)continue;if(d.type===type&&(target==null||d.target===target)&&(!d.objectiveLocation||d.objectiveLocation===(state.travelTo||state.player.location))&&(!d.objectiveLocations||d.objectiveLocations.includes(state.travelTo||state.player.location)))q.progress=(q.progress||0)+amount;}}
  function completeQuest(q){const d=W.quests.find(x=>x.id===q.id);if(!d)return;state.player.money+=d.reward;state.statistics.earnings+=d.reward;shiftRep(d.rep,d.repGain);grantXP(45+Math.round(d.reward/35),'задание');state.statistics.quests++;state.quests.completed.push(q.id);state.quests.active=state.quests.active.filter(x=>x!==q);if(q.id==='first_road'&&state.player.location==='garbage')q.step=1;notify(`Задание «${d.title}» выполнено · +${d.reward} ₽ · отношение «${W.factions[d.rep]?.name||d.rep}» улучшилось.`);}
  function questOnArrival(id){state.player.location=id;discover(id);if(!state.visited.includes(id))state.visited.push(id);for(const q of [...state.quests.active]){const d=W.quests.find(x=>x.id===q.id);if(d.type==='visit'&&d.target===id)completeQuest(q);if(d.type==='route'&&id===d.target){q.step=1;notify(`${W.locations[d.target].name} достигнута. Вернись: ${W.locations[d.returnTo].name}.`);}else if(d.type==='route'&&id===d.returnTo&&q.step===1)completeQuest(q);}if(id==='pripyat'&&state.worldFlags.documentsFound&&!state.worldFlags.stationOpen){state.worldFlags.stationOpen=true;notify('Документы раскрыли доступ к ЧАЭС.');}for(const n of W.locations[id].neighbors)discover(n);objectiveProgress('visit',id);}
  function arrive(id){state.travelTo=null;resetExploration();state.event=null;state.mode='play';state.panelReturn=null;state.player.trips++;questOnArrival(id);log(`Прибытие: ${W.locations[id].name}.`);document.body.classList.add('travel-transition');setTimeout(()=>document.body.classList.remove('travel-transition'),560);emit();}
  function choiceAvailable(choice){const when=choice.when||{},p=state.player;if(when.faction&&state.factionMembership!==when.faction)return false;if(when.factionMissing&&state.factionMembership)return false;if(when.minRank&&p.rank<when.minRank)return false;if(when.knowledge&&!state.knowledge.includes(when.knowledge))return false;if(when.background&&!([].concat(when.background).includes(state.backgroundId)))return false;if(when.questReady&&!questReady(when.questReady))return false;if(when.money!=null&&p.money<when.money)return false;if(when.items&&Object.entries(when.items).some(([id,n])=>count(id)<n))return false;if(when.attributes&&Object.entries(when.attributes).some(([key,n])=>(state.attributes?.[key]||0)<n))return false;if(when.rep&&Object.entries(when.rep).some(([f,n])=>(state.reputation[f]||0)<n))return false;if(when.questActive&&!state.quests.active.some(q=>q.id===when.questActive))return false;if(when.questMissing&&(state.quests.active.some(q=>q.id===when.questMissing)||state.quests.completed.includes(when.questMissing)))return false;if(when.flag&&!state.worldFlags[when.flag])return false;if(when.time==='night'&&!(p.time>=21||p.time<5))return false;if(when.time==='day'&&(p.time<5||p.time>=21))return false;return true;}
  function eventEligible(event,kind,loc,depth){if(!((event.kind===kind||event.kind==='both')&&loc.danger>=(event.minDanger||0)))return false;if(event.tags&&!event.tags.some(tag=>loc.tags?.includes(tag)))return false;if(event.locations&&!event.locations.includes(state.travelTo||state.player.location))return false;if(event.minDepth&&depth<event.minDepth)return false;if(event.maxDepth&&depth>event.maxDepth)return false;if(event.time==='night'&&!(state.player.time>=21||state.player.time<5))return false;if(event.time==='day'&&(state.player.time<5||state.player.time>=21))return false;if(event.requiredRep&&Object.entries(event.requiredRep).some(([f,n])=>(state.reputation[f]||0)<n))return false;if(event.requiredQuest&&!state.quests.active.some(q=>q.id===event.requiredQuest))return false;if(event.requiredFlag&&!state.worldFlags[event.requiredFlag])return false;if(event.requiredKnowledge&&!state.knowledge.includes(event.requiredKnowledge))return false;if(event.unique&&state.seenEvents.includes(event.id))return false;if(event.requiredFaction&&state.factionMembership!==event.requiredFaction)return false;return true;}
  function eventWeight(event,depth,locationId){const base={common:1,uncommon:.2,rare:.035,very_rare:.008,special:.0015}[event.rarity||'common']||1;const depthFactor=1+Math.min(depth,10)*(event.rarity==='common'?.015:event.rarity==='uncommon'?.07:event.rarity==='rare'?.12:event.rarity==='very_rare'?.16:.1);let weight=base*depthFactor*(state.seenEvents.includes(event.id)?.45:1);if(event.locations?.includes(locationId))weight*=1.8;if(event.requiredRep)weight*=1.1;if(event.requiredQuest)weight*=1.2;return Math.min(event.rarity==='special'?.06:event.rarity==='very_rare'?.2:2,weight);}
  function candidates(kind,locationId=state.player.location){const loc=W.locations[locationId]||W.locations[state.player.location],depth=state.expedition.active?state.expedition.depth:0,all=W.events.filter(event=>eventEligible(event,kind,loc,depth));const cooldown=all.filter(event=>!state.recentEvents.includes(event.id));return cooldown.length?cooldown:all;}
  function eventChance(dest){const to=W.locations[dest],p=state.player,gear=passive().protection,rep=state.reputation.loners||0,carry=Math.max(0,weight()-capacity()*.7),night=p.time>=21||p.time<5;return clamp(28+to.danger*5.4-gear*20-rep*.07+carry*.8+(p.stamina<25?9:0)+(night?9:0)+(p.hunger>80||p.thirst>80?7:0),15,88);}
  function stagesOf(definition){return definition.stages||[{id:'main',text:definition.text,choices:definition.choices}];}
  function setEventStage(definition,stageId,flow){const stages=stagesOf(definition),index=stages.findIndex(stage=>stage.id===stageId),stage=stages[index>=0?index:0];flow.stageId=stage.id;flow.stageIndex=index>=0?index:0;flow.phase='choices';flow.pending=null;flow.resultText='';flow.completionXP=0;if(!flow.visitedStages.includes(stage.id))flow.visitedStages.push(stage.id);state.event={id:definition.id,category:definition.category,rarity:definition.rarity||'common',text:stage.text||definition.text||'',choices:stage.choices||[],flow};state.mode='event';}
  function startEvent(definition,origin='travel',previousFlow=null){if(!definition)return null;let flow=previousFlow?clone(previousFlow):{version:1,stageId:'',stageIndex:0,phase:'choices',origin,chain:[],visitedStages:[],claimedActions:[],history:[],flags:{},pending:null,resultText:'',lastChoice:''};flow.origin=flow.origin||origin;flow.chain=flow.chain||[];if(!flow.chain.includes(definition.id))flow.chain.push(definition.id);flow.chain=flow.chain.slice(-8);flow.claimedActions=flow.claimedActions||[];flow.visitedStages=flow.visitedStages||[];flow.history=flow.history||[];flow.completionXP=flow.completionXP||0;flow.flags=flow.flags||{};if(!state.seenEvents.includes(definition.id))state.seenEvents.push(definition.id);if(['rare','very_rare','special'].includes(definition.rarity))window.ZoneRPGAudio?.play('rare');setEventStage(definition,stagesOf(definition)[0].id,flow);return state.event;}
  function triggerEvent(kind,locationId,origin=kind==='explore'?'explore':'travel'){const options=candidates(kind,locationId);if(!options.length)return null;const depth=state.expedition.active?state.expedition.depth:0,total=options.reduce((sum,event)=>sum+eventWeight(event,depth,locationId),0);let roll=Math.random()*total,selected=options[options.length-1];for(const event of options){roll-=eventWeight(event,depth,locationId);if(roll<=0){selected=event;break;}}if(state.expedition.active){state.expedition.history.push(selected.id);state.expedition.history=state.expedition.history.slice(-32);}state.recentEvents.push(selected.id);state.recentEvents=state.recentEvents.slice(-6);return startEvent(clone(selected),origin);}
  function completionKey(event=state.event){if(!event||event.id.startsWith('arrival_search_')||event.flow?.origin==='arrival')return null;return (event.id.startsWith('arrival_news_')?'camp_news':event.id)+':'+(state.explorationOriginLocationId||state.travelTo||state.player.location);}
  function claimEventCompletion(){const event=state.event,flow=event?.flow;if(!flow||flow.phase!=='result'||flow.pending?.nextStage||flow.pending?.nextEvent||flow.flags.completionPaid)return;const key=completionKey(event);flow.flags.completionPaid=true;flow.completionXP=key&&!state.eventXPClaims.includes(key)?({common:8,uncommon:12,rare:20,very_rare:30,special:28,unique:36}[event.rarity||'common']||8):0;if(key&&!state.eventXPClaims.includes(key))state.eventXPClaims.push(key);if(flow.completionXP)grantXP(flow.completionXP,'событие завершено');}
  function resetExploration(){state.expedition=X.empty();X.project(state);}
  function selectMutant(){const id=state.travelTo||state.player.location,options=W.mutantOptions(id,state.player.time,state.expedition.active?state.expedition.depth:0);let roll=Math.random()*options.reduce((n,x)=>n+x.weight,0);for(const x of options){roll-=x.weight;if(roll<=0)return x.id;}return options[options.length-1]?.id||'dog';}
  function showEventResult(text,pending={}){if(!state.event)return;const flow=state.event.flow;flow.phase='result';flow.pending={nextStage:pending.nextStage||null,nextEvent:pending.nextEvent||null,finish:Boolean(pending.finish),winText:pending.winText||'',fleeText:pending.fleeText||''};flow.completionXP=0;flow.resultText=text||'Решение принято. Пора решить, продолжать ли вылазку.';state.event.text=flow.resultText;state.event.choices=[{label:flow.pending.nextStage||flow.pending.nextEvent?'Следующий этап':'Продолжить',action:'advance'}];state.mode='event';state.panelReturn=null;claimEventCompletion();emit();}
  function finishEventFlow(returnToOrigin=false){const flow=state.event?.flow,origin=flow?.origin,search=origin==='explore'&&state.expedition.active,cost=X.cost(state.expedition.depth);if(search&&!returnToOrigin&&state.player.stamina<cost)return notify('Для следующего поиска нужно '+cost+' выносливости. Вернись и передохни.');deferEmission++;try{claimEventCompletion();const home=state.expedition.originLocationId;state.event=null;state.panelReturn=null;if(returnToOrigin){state.travelTo=null;if(search&&W.locations[home]){state.player.location=home;discover(home);if(!state.visited.includes(home))state.visited.push(home);const t=state.expedition.summary;log('Вылазка завершена: '+state.expedition.depth+' встреч · '+t.hours+' ч · '+t.kills+' побед · '+t.xp+' XP.');}if(search)state.lastExpedition=clone(state.expedition);resetExploration();state.mode='play';return;}if(origin==='travel'&&state.travelTo){arrive(state.travelTo);return;}if(search){state.player.location=home;explore();}else{resetExploration();state.mode='play';}}finally{deferEmission--;emit();}}
  function advanceEvent(){const event=state.event,flow=event?.flow;if(!event||!flow)return;const pending=flow.pending||{};if(pending.nextStage&&!W.events.find(e=>e.id===event.id)?.stages?.some(s=>s.id===pending.nextStage)){console.warn('[ZoneRPG] Недопустимое продолжение события',{eventId:event.id,nextStage:pending.nextStage});return notify('Не удалось открыть следующий этап. Сохрани вылазку; текущая встреча сохранена.');}if(pending.nextEvent&&!W.events.some(e=>e.id===pending.nextEvent)){console.warn('[ZoneRPG] Неизвестное продолжение события',pending.nextEvent);return notify('Не удалось открыть продолжение. Текущая встреча сохранена.');}if(pending.nextStage){const definition=W.events.find(item=>item.id===event.id);if(definition&&stagesOf(definition).some(stage=>stage.id===pending.nextStage)){setEventStage(definition,pending.nextStage,flow);emit();return;}}if(pending.nextEvent){const next=W.events.find(item=>item.id===pending.nextEvent);if(next&&!flow.chain.includes(next.id)&&flow.chain.length<8){startEvent(next,flow.origin,flow);emit();return;}}finishEventFlow();}
  function returnFromEvent(){const flow=state.event?.flow;if(!state.event||state.combat||flow?.phase!=='result'||flow.pending?.nextStage||flow.pending?.nextEvent)return;finishEventFlow(true);}
  function travel(id){if(state.expedition.active)return notify('Нельзя перейти в другую локацию во время вылазки.');if(state.event||state.combat)return notify('Сначала закончи текущую встречу.');const loc=W.locations[state.player.location];if(!loc.neighbors.includes(id)||!unlocked(id)||routeBlocked(state.player.location,id))return notify('Этот путь пока закрыт.');if(state.player.stamina<4)return notify('Сил не хватает. Отдохни или выпей энергетик.');const dest=W.locations[id],p=state.player;resetExploration();state.travelTo=id;const cost=5+dest.danger*2+(weight()>capacity()?8:0);p.stamina=clamp(p.stamina-cost,0,finalStats().maxStamina);p.hunger=clamp(p.hunger+needDrain(5+dest.danger));p.thirst=clamp(p.thirst+needDrain(7+dest.danger));advanceClock(1);const res=passive();p.radiation=clamp(p.radiation+dest.rad*.15*(1-res.radResist)+res.radPerTrip);if(p.radiation>=80){const dose=Math.ceil((p.radiation-75)/10);p.health=clamp(p.health-dose,0,finalStats().maxHealth);notify(`Критический фон повреждает здоровье: −${dose}.`);}p.health=clamp(p.health-(p.hunger>80?3:0)-(p.thirst>80?4:0),0,finalStats().maxHealth);if(p.radiation>=20)p.stamina=clamp(p.stamina-(p.radiation>=50?8:3),0,finalStats().maxStamina);log(`Переход · ${dest.name}: −${cost} выносливости, +${5+dest.danger}% голода, +${7+dest.danger}% жажды.`);if(p.health<=0)return die();const chance=eventChance(id);if(Math.random()*100<chance){const e=triggerEvent('travel',id);if(e){emit();return;}}arrive(id);}
  function setAmbientEvent(){const loc=W.locations[state.player.location],intro=state.player.trips===0?S.BACKGROUNDS[state.backgroundId].intro:'';state.event={id:'arrival_'+state.player.trips,category:'Локация',text:(intro?intro+' ':loc.layout+'. ')+loc.description,choices:[{label:'Осмотреться',action:'dismiss'},{label:'Открыть карту',action:'map'}],flow:{version:1,stageId:'arrival',stageIndex:0,phase:'choices',origin:'arrival',chain:[],visitedStages:['arrival'],claimedActions:[],flags:{},pending:null,resultText:'',lastChoice:''}};state.mode='event';}
  function setEmptySearchEvent(locationId,depth){const id='arrival_search_'+locationId+'_'+depth,loc=W.locations[locationId];state.event={id,category:'Исследование',text:'Ты проверяешь сектор «'+loc.name+'», но находишь только пустые гильзы. Можно искать дальше или вернуться в укрытие.',choices:[{label:'Продолжить',action:'advance'}],flow:{version:1,stageId:'search',stageIndex:0,phase:'result',origin:'explore',chain:[id],visitedStages:['search'],claimedActions:[],flags:{completionPaid:true},completionXP:0,pending:{finish:true},resultText:'Поиск окончен. Полезных находок нет.',lastChoice:''}};state.mode='event';}

  function worldModifier(key,location=state.player.location){return state.worldEvents.reduce((n,a)=>{const d=W.worldEvents.find(x=>x.id===a.id);return n+(d?.locations.includes(location)?d[key]||0:0);},0);}
  function advanceClock(hours){state.player.time=(state.player.time+hours)%24;const before=state.worldClock;state.worldClock+=hours;if(state.expedition.active)state.expedition.summary.hours+=hours;state.worldEvents=state.worldEvents.filter(x=>x.endsAt>state.worldClock);if(Math.floor(before/12)!==Math.floor(state.worldClock/12)){const d=rand(W.worldEvents);state.worldEvents=state.worldEvents.filter(x=>x.id!==d.id);state.worldEvents.push({id:d.id,endsAt:state.worldClock+d.duration});log('[РАДИО] '+d.name+': '+d.description);}}
  function questUnlocked(q){return(!q.requiredFaction||q.requiredFaction===state.factionMembership)&&(!q.requiredCompletedQuest||state.quests.completed.includes(q.requiredCompletedQuest));}
  function factionStatus(id){const f=W.factions[id],rep=state.reputation[id]||0;return{...f,id,rep,tier:rep<=-40?'Враг':rep<0?'Недоверие':rep<20?'Нейтрально':rep<50?'Друг':'Союзник',member:state.factionMembership===id,canJoin:Boolean(f.joinable&&!state.factionMembership&&state.player.location===f.base&&rep>=f.minRep&&state.player.rank>=f.minRank)};}
  function joinFaction(id){const f=factionStatus(id);if(!f.canJoin)return notify('Вступление недоступно: нужны база, ранг '+f.minRank+' и репутация '+f.minRep+'.');state.factionMembership=id;for(const enemy of f.enemies||[])shiftRep(enemy,-15);shiftRep(id,5);notify('Ты вступил: '+f.name+'. Открыты контракты и скидки.');}
  function leaveFaction(){if(!state.factionMembership)return;shiftRep(state.factionMembership,-15);state.factionMembership=null;notify('Ты покинул группировку. Контракты остаются в журнале, но новые пока недоступны.');}
  function routeBlocked(from,to){return state.worldEvents.some(a=>W.worldEvents.find(d=>d.id===a.id)?.blockedRoads?.some(([x,y])=>(x===from&&y===to)||(x===to&&y===from)));}
  function shopFactor(faction){return clamp(1-(state.reputation[faction]||0)*.001-(state.factionMembership===faction?.08:0)-worldModifier('discount'),.65,1.25);}
  function explore(){if(state.event||state.combat)return notify('Сначала разберись с текущей ситуацией.');const id=state.expedition.active?state.expedition.originLocationId:state.player.location,loc=W.locations[id],cost=X.cost(state.expedition.depth);if(state.player.stamina<cost)return notify('Не хватает сил на поиск: нужно '+cost+'.');if(!state.expedition.active){state.expedition=X.empty();state.expedition.active=true;state.expedition.originLocationId=id;}state.player.location=id;state.expedition.depth++;X.project(state);discover(id);const p=state.player;p.stamina=clamp(p.stamina-cost,0,finalStats().maxStamina);p.hunger=clamp(p.hunger+needDrain(1));p.thirst=clamp(p.thirst+needDrain(2));advanceClock(1);p.radiation=clamp(p.radiation+(loc.rad*.1+worldModifier('radiation',id))*(1-passive().radResist));state.explores[id]=(state.explores[id]||0)+1;state.explorationCount=(state.explorationCount||0)+1;objectiveProgress('explore',id);const regen=passive().healthRegen||0;if(regen>0)p.health=clamp(p.health+regen,0,finalStats().maxHealth);if(p.hunger>=80)notify('ГОЛОД: найди еду.');if(p.thirst>=80)notify('ЖАЖДА: нужна вода.');if(p.radiation>=85){p.health=clamp(p.health-1,0,finalStats().maxHealth);if(p.health<=0)return die();}const night=p.time>=21||p.time<5,chance=clamp(64+(loc.danger+worldModifier('danger',id))*2+X.tier(state.expedition.depth)*2+(night?8:0),44,84);if(Math.random()*100<chance)triggerEvent('explore',id,'explore');if(!state.event){setEmptySearchEvent(id,state.expedition.depth);state.expedition.history.push(state.event.id);state.expedition.history=state.expedition.history.slice(-32);}emit();}
  function pickLoot(type='common'){const lists={common:['wires','bread','water','ammo918','valuables','parts','canned'],military:['ammo545','ammo762','bandage','electronics','parts'],medical:['medkit','bandage','antirad','canned']};if(type==='artifact'){const depth=state.expedition.active?state.expedition.depth:0,loc=W.locations[state.player.location],gear=finalStats(),chance=clamp(.035+Math.min(depth,10)*.006+loc.danger*.008+(state.player.time>=21||state.player.time<5?.025:0)+(gear.artifactFindChance||0),.015,.28);if(Math.random()>chance)return null;const table=[['jellyfish','stoneflower','meatchunk','spark','bubble'],['flash','gravi','shell','fireball','moonlight','battery'],['nightstar','goldfish','soul','needle'],['motherBeads']];const roll=Math.random(),pool=roll<.015?table[3]:roll<.09?table[2]:roll<.38?table[1]:table[0],id=rand(pool);return add(id,1)?id:null;}let pool=lists[type]||lists.common;if(type==='common'&&environment().danger>4)pool=pool.concat(lists.military);const offset=Math.floor(Math.random()*pool.length);for(let n=0;n<pool.length;n++){const id=pool[(offset+n)%pool.length];if(add(id,1))return id;}return null;}
  function eventFlavor(kind,item){const name=I.items[item]?.name||'припасы';return (kind==='gift'?'Переданы припасы. ':'Найдена добыча. ')+'Получено: '+name+'.';}
  function applyEffects(effects){const p=state.player;if(!effects)return true;if(effects.itemCost&&Object.entries(effects.itemCost).some(([id,n])=>count(id)<n)){const id=Object.keys(effects.itemCost).find(x=>count(x)<effects.itemCost[x]);notify(`Не хватает: ${I.items[id].name}. Остальные последствия этого выбора отменены.`);return false;}if(effects.money<0&&p.money<-effects.money){notify('У тебя не хватает денег на этот выбор. Остальные последствия отменены.');return false;}if(effects.money<0&&effects.add){const requiredWeight=Object.entries(effects.add).reduce((total,[id,n])=>total+(I.items[id]?.weight||0)*n,0);if(weight()+requiredWeight>capacity()+1e-7){notify('В рюкзаке нет места для покупки. Деньги не списаны.');return false;}}for(const k of ['health','stamina','hunger','thirst','radiation'])if(effects[k])p[k]=clamp(p[k]+effects[k],0,k==='health'?finalStats().maxHealth:k==='stamina'?finalStats().maxStamina:100);if(effects.money){const amount=effects.money;if(state.expedition.active)state.expedition.summary.money+=Math.max(0,amount);p.money=Math.max(0,p.money+amount);if(amount>0)state.statistics.earnings+=amount;}
    if(effects.rep)Object.entries(effects.rep).forEach(([f,n])=>shiftRep(f,n));if(effects.itemCost)Object.entries(effects.itemCost).forEach(([id,n])=>{if(remove(id,n))notify(`Потрачено: ${I.items[id].name}.`);else notify(`Не хватает: ${I.items[id].name}.`);});if(effects.add)Object.entries(effects.add).forEach(([id,n])=>{const got=add(id,n);if(got)notify(`Получено: ${I.items[id].name} ×${got}.`);else notify('В рюкзаке нет места для находки.');});if(effects.lootRoll||effects.riskRoll){const id=pickLoot();if(id)notify(eventFlavor('loot',id));else notify('Рюкзак полон, находку пришлось оставить.');}
    if(effects.electronicsRoll){if(Math.random()<.48&&add('electronics',1))notify('В обломках нашлась рабочая плата.');else notify('Электроника повреждена или рюкзак перегружен.');}if(effects.artifactRoll){const id=pickLoot('artifact');if(id){state.statistics.artifacts++;p.artifacts++;const rarity=I.items[id].rarity||'common';const text=rarity==='very_rare'||rarity==='anomalous'?'ОБНАРУЖЕН '+(rarity==='anomalous'?'АНОМАЛЬНЫЙ':'ОЧЕНЬ РЕДКИЙ')+' АРТЕФАКТ: '+I.items[id].name:'Найден артефакт: '+I.items[id].name;notify(text);window.ZoneRPGAudio?.play('rare');document.body.classList.add('feedback-rare');setTimeout(()=>document.body.classList.remove('feedback-rare'),700);}else if(weight()>capacity())notify('Артефактный сигнал был слабым или рюкзак перегружен.');else notify('Дозиметр стихает: в этот раз артефакта нет.');}if(effects.questRoll){const d=W.quests.find(q=>q.id==='field_notes');if(p.location==='yantar'&&d&&!state.worldFlags.documentsFound&&add('documents')){state.worldFlags.documentsFound=true;notify('Получены документы лаборатории. Координаты указывают на северный сектор.');}else{const id=pickLoot('medical');if(id)notify(eventFlavor('gift',id));}}if(effects.talkRoll){const chance=clamp(58+(state.reputation.loners||0)*.2+p.stamina*.12,25,88);if(Math.random()*100<chance){p.money+=60;shiftRep('bandits',2);notify(`Переговоры удались (шанс ${Math.round(chance)}%). Бандиты уступили за 60 ₽.`);}else {p.health=clamp(p.health-12,0,finalStats().maxHealth);notify(`Договориться не вышло (шанс ${Math.round(chance)}%). В драке ты потерял 12 здоровья.`);}}
    if(effects.fleeRoll){const chance=clamp(68+p.stamina*.18-environment().danger*4,20,93);if(Math.random()*100>chance){p.health=clamp(p.health-9,0,finalStats().maxHealth);notify(`Отступление сорвалось (шанс ${Math.round(chance)}%). Получено 9 урона.`);}else notify(`Ты ушёл от опасности (шанс ${Math.round(chance)}%).`);}
    if(effects.detectRoll){const chance=clamp(48+p.stamina*.22+Math.max(0,state.attributes.perception-2)*2+(state.equipment.weapon==='knife'?8:0),25,91);notify(`Проверка: ${Math.round(chance)}% шанс заметить опасность.`);if(Math.random()*100<chance)notify('Ты заметил безопасный подход.');else {p.radiation=clamp(p.radiation+4);notify('Проверка не выявила угрозу; фон немного вырос.');}}
    if(effects.riskRoll&&Math.random()<.32){const hit=Math.round(5+environment().danger*1.4);p.health=clamp(p.health-hit,0,finalStats().maxHealth);notify(`Ловушка сработала: −${hit} здоровья.`);}if(effects.researchQuest){const q=state.quests.active.find(x=>x.id===effects.researchQuest),def=W.quests.find(x=>x.id===effects.researchQuest);if(q&&def&&state.player.location===def.target)q.progress=Math.min(def.count,q.progress+1);}if(effects.knowledge){const entries=Array.isArray(effects.knowledge)?effects.knowledge:[effects.knowledge];state.knowledge=[...new Set([...state.knowledge,...entries])].slice(-80);}if(effects.newsRoll){const loc=state.player.location,pool=['На северной дороге видели мутантов. Держи магазин полным.','Торговец на Кордоне меняет медикаменты на детали.','У старой вышки снова слышали аварийный сигнал.','После заката у промзоны чаще встречаются бандиты.','Разведчик заметил тихий обход к ближайшему сектору.','Учёные ищут образцы аномалий и платят за целые находки.','Кто-то оставил записку о тайнике под бетонным кольцом.','Патруль предупреждает: дозиметры у воды часто врут.'];pool.push(...(W.rumors[loc]||[]));const text=pool[(Math.floor(Math.random()*pool.length)+state.explorationCount)%pool.length];state.knowledge=[...new Set([...state.knowledge,'rumor:'+loc])];state.rumors.push({text,location:W.locations[loc].name,time:state.player.time,depth:state.explores[loc]||0});state.rumors=state.rumors.slice(-30);state.knowledge=[...new Set([...state.knowledge,'camp news '+loc])].slice(-80);notify('СЛУХ · '+text);}if(effects.startQuest){for(const id of (Array.isArray(effects.startQuest)?effects.startQuest:[effects.startQuest])){const quest=W.quests.find(q=>q.id===id);if(quest&&!state.quests.active.some(q=>q.id===id)&&!state.quests.completed.includes(id)){state.quests.active.push({id,step:quest.type==='route'&&state.player.location===quest.target?1:0,progress:0,acceptedAtLocation:state.player.location});notify('Записано поручение: '+quest.title+'.');}}}if(effects.flags)Object.entries(effects.flags).forEach(([k,v])=>state.worldFlags[k]=v);if(effects.discoverRoll)maybeReveal();if(effects.tradeRoll){const id=remove('parts',1)?'parts':remove('wires',2)?'wires':null;if(id){p.money+=id==='parts'?150:90;notify(`Обмен завершён: +${id==='parts'?150:90} ₽.`);}else notify('Для обмена нужны детали или два мотка провода.');}if(effects.time){advanceClock(effects.time);}if(p.radiation>=25)notify('Дозиметр предупреждает: фон повышен. Антирад поможет снизить нагрузку.');if(p.health<=0){die();return false;}return true;}
  function chooseEvent(index){const event=state.event,visible=event?.choices?.filter(choiceAvailable)||[];if(!event||!visible[index])return;const choice=visible[index],flow=event.flow;if(choice.action==='joinFaction'){joinFaction(choice.factionId);if(state.factionMembership===choice.factionId)showEventResult('Твоё вступление записано. Контракты базы доступны в журнале.',{finish:true});return;}if(choice.action==='questPanel'){state.panelReturn='event';state.mode='quests';emit();return;}if(choice.action==='turnIn'){const completed=turnIn(choice.questId);if(completed)showEventResult('Заказчик принял отчёт и выдал награду.',{finish:true});return;}if(choice.action==='advance'){advanceEvent();return;}if(choice.action==='return'){returnFromEvent();return;}if(choice.action==='dismiss'){finishEventFlow();return;}if(choice.action==='map'){state.panelReturn='event';state.mode='map';emit();return;}if(!flow)return;const actionKey=`${event.id}:${flow.stageId}:${choice.label}`;if(flow.claimedActions.includes(actionKey))return;flow.history=flow.history||[];flow.history.push({text:event.text,choice:choice.label});flow.history=flow.history.slice(-8);const effects=flow.flags['legacyEffects:'+flow.stageId]?{}:(choice.effects||{});if(choice.when?.background){const key=event.id+':'+choice.label;if(!state.backgroundInteractions.includes(key))state.backgroundInteractions.push(key);}const definition=W.events.find(e=>e.id===event.id),stage=definition&&stagesOf(definition).find(s=>s.id===flow.stageId);const nextStage=choice.nextStage||effects.nextStage||stage?.nextStage||null,nextEvent=choice.nextEvent||effects.nextEvent||stage?.nextEvent||null,pending={nextStage,nextEvent,finish:choice.finish===true||(!nextStage&&!nextEvent),winText:choice.winText||'',fleeText:choice.fleeText||''};if(choice.combat){if(!applyEffects(effects)||state.mode==='dead')return;flow.claimedActions.push(actionKey);flow.lastChoice=choice.label;startCombat(choice.enemyId||event.enemyId||definition?.enemyId||(choice.combat==='autoMutant'?selectMutant():choice.combat),pending);return;}if(!applyEffects(effects)||state.mode==='dead')return;flow.claimedActions.push(actionKey);flow.lastChoice=choice.label;showEventResult((choice.resultText||`${choice.label}. Ты решаешь и продолжаешь осторожно.`)+(effects.newsRoll&&state.rumors.length?' Слух: '+state.rumors[state.rumors.length-1].text:''),pending);}
  function startCombat(type,eventPending=null){if(!W.enemyTypes[type]){console.warn('[ZoneRPG] Неизвестный противник',type);notify('Контакт не удалось определить. Сохрани игру и вернись к текущей встрече.');return;}if(!state.discoveredEnemies.includes(type)){state.discoveredEnemies.push(type);log('Справочник: новый противник '+W.enemyTypes[type].name+'.');}const enemy=clone(W.enemyTypes[type]);const scale=1+(state.expedition.active?X.tier(state.expedition.depth)*.08:0);enemy.hp=Math.ceil(enemy.hp*scale);enemy.damage=Math.ceil(enemy.damage*scale);enemy.visual=enemy.visual||type;const intro=enemy.intro||({boar:'Кабан срывается с места и несётся прямо на тебя.',bloodsucker:'Из искажённого воздуха выныривает кровосос.',dog:'Стая рвётся из травы, сбивая прицел.',snork:'Снорк падает с обломков и перекрывает путь.',pseudogiant:'Земля глухо дрожит под тяжёлой поступью мутанта.',bandit:'Бандит резко вскидывает оружие.',merc:'Наёмник занимает позицию и открывает огонь.',duty:'Патруль «Долга» принимает тебя за угрозу.',monolith:'Боец Монолита не отвечает на оклик.'})[type]||`${enemy.name} атакует без предупреждения.`;state.combat={lootCollected:false,scale,type,enemy:{...enemy,maxHp:enemy.hp},intro,aimed:false,status:'ОПАСНОСТЬ',log:[intro],turn:1};window.ZoneRPGAudio?.play('alert');document.body.classList.add('combat-start');setTimeout(()=>document.body.classList.remove('combat-start'),520);if(eventPending&&state.event?.flow){state.event.flow.phase='combat';state.event.flow.pending=eventPending;}else state.event=null;state.mode='combat';state.panelReturn=null;notify(`Бой: ${enemy.name} · ${enemy.hp} здоровья. Выбери действие.`);emit('combat');}
  function combatLog(text){state.combat.log.push(text);state.combat.log=state.combat.log.slice(-6);log(text);}
  function enemyHit(){if(!state.combat)return;const c=state.combat,p=state.player,e=c.enemy,armor=finalStats();if(e.windup&&c.turn%e.windup===1){c.status='ПРОТИВНИК ГОТОВИТ УДАР';combatLog(e.name+' готовит тяжёлую атаку. Можно прицелиться, лечиться или отступить.');c.turn++;return;}const hit=Math.random()<e.accuracy*(1-(armor.evasion||0));if(hit){c.status='ПОЛУЧЕН УРОН';const raw=Math.round(e.damage*(e.windup?1.4:1)*(.84+Math.random()*.32)),loss=Math.max(1,Math.round(raw*(1-armor.protection)));p.health=clamp(p.health-loss,0,finalStats().maxHealth);if(e.radiationOnHit){const dose=Math.max(0,e.radiationOnHit*(1-armor.radResist));p.radiation=clamp(p.radiation+dose);combatLog('Радиоактивное заражение: +'+dose.toFixed(1)+'% фона.');}combatLog(e.name+' попадает: −'+loss+' здоровья (урон '+raw+', защита '+Math.round(armor.protection*100)+'%).');window.ZoneRPGAudio?.play('damage');document.body.classList.add('feedback-damage');setTimeout(()=>document.body.classList.remove('feedback-damage'),240);}else{c.status='ВРАГ ПРОМАХНУЛСЯ';combatLog(e.name+' промахивается.');}c.turn++;if(p.health<=0)die();}
  function defeatEnemy(){const c=state.combat;if(!c||c.lootCollected)return;c.lootCollected=true;const e=c.enemy,p=state.player,flow=state.event?.flow?.phase==='combat'?state.event.flow:null;grantXP(e.xp,'победа в бою');p.kills++;state.statistics.kills++;const cash=Math.round(20+Math.random()*55);p.money+=cash;const drops=e.loot.filter(id=>Math.random()<(e.lootChances?.[id]??.6));const collected=drops.filter(id=>add(id)>0);if(state.expedition.active){state.expedition.summary.kills++;state.expedition.summary.money+=cash;}if(flow){flow.rewards={xp:(flow.rewards?.xp||0)+e.xp,money:(flow.rewards?.money||0)+cash,items:[...(flow.rewards?.items||[]),...collected.map(id=>({id,name:I.items[id].name,qty:1}))]};flow.history=flow.history||[];flow.history.push({text:`${e.name} повержен.`,choice:'Бой'});flow.history=flow.history.slice(-8);}shiftRep(e.faction,-5);if(e.faction==='mutants')objectiveProgress('kill','mutants');else if(['bandits','mercs'].includes(e.faction))objectiveProgress('kill','hostiles');log(`${e.name} повержен. +${e.xp} опыта; найдено: ${collected.map(x=>I.items[x].name).join(', ')||'ничего'}.`);window.ZoneRPGAudio?.play('victory');if(drops.length)window.ZoneRPGAudio?.play('loot');document.body.classList.add('feedback-loot');setTimeout(()=>document.body.classList.remove('feedback-loot'),600);state.combat=null;if(flow){state.mode='event';showEventResult(flow.pending?.winText||`Противник повержен. Ты проверяешь добычу и возвращаешься к делу.`,flow.pending||{});return;}state.event=null;state.mode='play';state.panelReturn=null;if(state.travelTo)arrive(state.travelTo);else emit();}
  function attack(){if(!state.combat)return;const p=state.player,id=weaponItem()?.id;syncWeaponAlias();const weapon=I.weapons[I.items[id]?.weaponId];if(!weapon)return notify('Нет оружия в руках. Экипируй нож, пистолет или основное оружие.');const c=state.combat,ammo=weapon.ammoType,mag=state.magazines[id]||0;if(ammo&&mag<=0){combatLog('Магазин пуст. Перезаряди оружие.');return enemyHit();}if(ammo&&Math.random()>(passive().ammoSave||0))state.magazines[id]--;improveMastery(weapon);window.ZoneRPGAudio?.play('shot');document.body.classList.add('feedback-shot');setTimeout(()=>document.body.classList.remove('feedback-shot'),140);const skill=(state.weaponMastery[masteryKey(weapon)]||0)/100;let chance=weapon.accuracy+(c.aimed?.18:0)+(p.stamina-50)*.002-(p.hunger>75?.12:0)-(p.thirst>75?.1:0)+(passive().accuracy||0)+(state.attributes.agility-2)*.006+skill*.045;chance=clamp(chance-(c.enemy.evasion||0),.18,.96);c.aimed=false;if(Math.random()<chance){let damage=Math.round((weapon.damage+(passive().damage||0)+(weapon.weaponClass==='melee'?state.attributes.strength*.35:0))*(.82+Math.random()*.36)),critical=Math.random()<clamp(weapon.critChance+(passive().critChance||0)+skill*.03,0,.75);if(critical)damage=Math.round(damage*1.65);damage=Math.max(1,Math.round(damage*(1-c.enemy.armor)));c.enemy.hp-=damage;combatLog((critical?'Критическое попадание! ':'Попадание! ')+I.items[id].name+' наносит '+damage+' урона.');window.ZoneRPGAudio?.play('hit');document.body.classList.add('feedback-hit');setTimeout(()=>document.body.classList.remove('feedback-hit'),220);if(c.enemy.hp<=0)return defeatEnemy();}else{combatLog('Промах. Пуля уходит в укрытие.');window.ZoneRPGAudio?.play('miss');}enemyHit();}
  function aim(){if(!state.combat)return;state.combat.aimed=true;combatLog('Ты прицеливаешься. Следующий выстрел точнее на 18%.');enemyHit();}
  function reload(ref){const selected=ref?findItem(ref):weaponItem(),id=selected&&I.items[selected.id]?.type==='weapon'?selected.id:weaponItem()?.id,weapon=I.weapons[I.items[id]?.weaponId];if(!weapon)return notify('Нет оружия в руках.');if(!weapon.ammoType)return notify('Нож не требует перезарядки.');const need=weapon.magazine-(state.magazines[id]||0),have=count(weapon.ammoType);if(need<=0)return notify('Магазин уже полон.');if(!have)return notify('Нет боеприпасов '+I.items[weapon.ammoType].name+'.');const n=Math.min(need,have);remove(weapon.ammoType,n);state.magazines[id]=(state.magazines[id]||0)+n;log('Перезарядка: '+I.items[id].name+' · '+n+' шт.');window.ZoneRPGAudio?.play('reload');if(state.combat){combatLog('Перезаряжено: '+n+' шт. за '+weapon.reloadTime.toFixed(1)+' с.');enemyHit();}else notify('Магазин '+I.items[id].name+': '+state.magazines[id]+'/'+weapon.magazine+'.');}
  function combatUse(id){if(!state.combat)return;const index=state.inventory.findIndex(x=>x.id===id);if(index<0)return notify('Предмета нет в рюкзаке.');useItem(index);if(state.combat)enemyHit();}
  function flee(){if(!state.combat)return;const flow=state.event?.flow?.phase==='combat'?state.event.flow:null,chance=clamp(62+state.player.stamina*.2-W.locations[state.player.location].danger*4,18,92);if(Math.random()*100<chance){combatLog(`Уход удался (шанс ${Math.round(chance)}%).`);state.combat=null;state.player.stamina=clamp(state.player.stamina-8);if(flow){state.mode='event';showEventResult(flow.pending?.fleeText||'Ты отрываешься от противника и возвращаешься к событию.',flow.pending||{});return;}state.event=null;state.mode='play';state.panelReturn=null;if(state.travelTo)arrive(state.travelTo);else emit();}else{combatLog(`Не удалось оторваться (шанс ${Math.round(chance)}%).`);state.player.stamina=clamp(state.player.stamina-10);enemyHit();}}
  function useItem(index){const row=state.inventory[index];if(!row)return;const d=I.items[row.id],fx=d.effect;if(d.type==='artifact'){toggleArtifact(row.instanceId||row.id);return;}if(d.slot){equipGear(row.instanceId||row.id);return;}if(!fx||['ammo','loot','quest','weapon'].includes(d.type)){notify('Этот предмет нельзя использовать напрямую.');return;}if(fx.ammo)return notify('Боеприпасы можно зарядить в бою.');if(fx.repair)return notify('Снаряжение исправно.');for(const k of ['health','stamina'])if(fx[k])state.player[k]=clamp(state.player[k]+fx[k],0,k==='health'?finalStats().maxHealth:finalStats().maxStamina);for(const k of ['hunger','thirst','radiation'])if(fx[k])state.player[k]=clamp(state.player[k]+fx[k]);remove(row.id);notify(`Использован предмет: ${d.name}.`);if(fx.quest==='documents'){state.worldFlags.documentsFound=true;}
  }
  function equipGear(ref){const row=findItem(ref),item=I.items[row?.id],slot=item?.slot;if(!row||!slot||!['primary','sidearm','melee','armor','head','backpack','detector'].includes(slot))return notify('Этот предмет не подходит к слоту экипировки.');const old=state.equipment[slot];state.equipment[slot]=row.instanceId||row.id;if(['primary','sidearm','melee'].includes(slot))state.equipment.activeWeaponSlot=slot;syncWeaponAlias();state.player.health=Math.min(state.player.health,finalStats().maxHealth);state.player.stamina=Math.min(state.player.stamina,finalStats().maxStamina);notify('Экипировано: '+item.name+(old&&old!==(row.instanceId||row.id)?' вместо прежнего предмета.':'.')+(weight()>capacity()?' Вес выше лимита; предметы сохранены.':''));emit();}
  function equipWeapon(ref){const row=findItem(ref);if(I.items[row?.id]?.type!=='weapon')return notify('Этого оружия нет в рюкзаке.');equipGear(ref);}
  function equipArmor(ref){const row=findItem(ref);if(I.items[row?.id]?.type!=='armor')return notify('Брони нет в рюкзаке.');equipGear(ref);}
  function unequipSlot(slot){if(!['primary','sidearm','melee','armor','head','backpack','detector'].includes(slot)||!state.equipment[slot])return notify('Слот уже пуст.');const row=itemForSlot(slot),name=I.items[row?.id]?.name||'Снаряжение';state.equipment[slot]=null;if(slot===state.equipment.activeWeaponSlot){state.equipment.activeWeaponSlot=['sidearm','primary','melee'].find(key=>state.equipment[key])||'melee';syncWeaponAlias();}state.player.health=Math.min(state.player.health,finalStats().maxHealth);state.player.stamina=Math.min(state.player.stamina,finalStats().maxStamina);notify('Снято снаряжение: '+name+'.'+(weight()>capacity()?' Вес выше новой грузоподъёмности; вещи остались в рюкзаке.':''));emit();}
  function switchWeapon(slot){if(!['primary','sidearm','melee'].includes(slot)||!itemForSlot(slot))return notify('В этом слоте нет подходящего оружия.');state.equipment.activeWeaponSlot=slot;syncWeaponAlias();notify(`В руках: ${I.items[state.equipment.weapon].name}.`);emit();}
  function toggleArtifact(ref){const row=findItem(ref);if(!row||I.items[row.id]?.type!=='artifact')return notify('Артефакта нет в рюкзаке.');const instance=row.instanceId||row.id,list=state.equipment.artifacts,i=list.indexOf(instance);if(i>=0)list.splice(i,1);else if(list.length<4)list.push(instance);else return notify('Доступно четыре слота артефактов.');state.player.health=Math.min(state.player.health,finalStats().maxHealth);state.player.stamina=Math.min(state.player.stamina,finalStats().maxStamina);notify((i>=0?'Артефакт снят: ':'Артефакт экипирован: ')+I.items[row.id].name);emit();}
  function sell(ref,qty=1){const row=findItem(ref);if(!row||row.qty<qty)return notify('Предмета нет в рюкзаке.');const id=row.id;if(isEquipped(row.instanceId||row.id))return notify('Сначала сними экипированный предмет.');const npc=trader();if(!npc)return notify('Здесь нет торговца.');const factor=shopFactor(npc.faction),price=Math.max(1,Math.round(I.items[id].price*.52*factor));removeItem(ref,qty);state.player.money+=price*qty;state.statistics.earnings+=price*qty;notify(`Продано ${I.items[id].name} ×${qty} за ${price*qty} ₽.`);emit();}
  function drop(ref){const row=findItem(ref);if(!row)return notify('Предмета нет в рюкзаке.');const id=row.id;if(isEquipped(row.instanceId||row.id))return notify('Сначала сними экипированный предмет.');removeItem(ref);notify(`Оставлено в Зоне: ${I.items[id].name}.`);emit();}
  function trader(){const loc=W.locations[state.player.location],npc=loc.trader?W.people[loc.trader]:null;return npc&&(state.reputation[npc.faction]||0)>-40?npc:null;}
  function buy(id,qty=1){const npc=trader();if(!npc)return notify('Торговец сейчас недоступен.');const item=I.items[id];if(!item||!getShop().stock.some(row=>row.id===id))return notify('Этой позиции сейчас нет в продаже.');if(!Number.isInteger(qty)||qty<1)return;const factor=clamp(1-(state.reputation[npc.faction]||0)*.001,.8,1.25),price=Math.ceil(item.price*factor)*qty;if(state.player.money<price)return notify('Не хватает денег.');if(weight()+item.weight*qty>capacity()+1e-7)return notify('Рюкзак полон. Сними лишний вес.');if(add(id,qty)<qty)return notify('Рюкзак полон. Сними лишний вес.');state.player.money-=price;notify(`Куплено ${item.name} ×${qty} за ${price} ₽.`);emit();}
  function breath(){
    if(state.event||state.combat||state.player.health<=0)return notify('Сначала закончи текущую встречу.');
    const p=state.player,before=p.stamina;p.stamina=clamp(p.stamina+25,0,finalStats().maxStamina);advanceClock(1);p.hunger=clamp(p.hunger+needDrain(3));p.thirst=clamp(p.thirst+needDrain(4));
    notify('Передышка в укрытии: +'+Math.round(p.stamina-before)+' выносливости. Прошёл час; голод и жажда усилились.');
  }
  function rest(){if(state.event||state.combat)return notify('Сначала закончи текущую встречу.');const npc=trader(),loc=W.locations[state.player.location];if((!npc&&!loc.camp)||state.player.money<35)return breath();state.player.money-=35;advanceClock(2);state.player.health=clamp(state.player.health+25,0,finalStats().maxHealth);state.player.stamina=finalStats().maxStamina;state.player.hunger=clamp(state.player.hunger+7);state.player.thirst=clamp(state.player.thirst+8);state.player.radiation=clamp(state.player.radiation-4);notify('Передышка у костра: +25 здоровья, выносливость восстановлена, фон немного спал. Потрачено 35 ₽.');}
  function questOffers(){const local=W.locations[state.player.location].npcs;return W.quests.filter(q=>local.includes(q.giver)&&!state.quests.active.some(a=>a.id===q.id)&&!state.quests.completed.includes(q.id)&&questUnlocked(q)&&(!q.target||q.id!=='scout_pripyat'||state.known.includes('pripyat'))).map(q=>({...q,accepted:false}));}
  function acceptQuest(id){const d=W.quests.find(q=>q.id===id);if(!d||!questUnlocked(d)||state.quests.completed.includes(id)||state.quests.active.some(q=>q.id===id)||!W.locations[state.player.location].npcs.includes(d.giver))return;state.quests.active.push({id,step:0,progress:0,acceptedAtLocation:state.player.location});notify(`Принято задание: ${d.title}.`);}
  function npcAction(value){const [id,act]=value.split(':');const npc=W.people[id];if(!npc||!W.locations[state.player.location].npcs.includes(id))return notify('Этого человека здесь нет.');if(act==='fight')return startCombat(npc.enemyId||(npc.faction==='military'?'military':npc.faction==='mercs'?'merc':npc.faction==='duty'?'duty':npc.faction==='monolith'?'monolith':npc.faction==='bandits'?'bandit':'rookie'));if((state.reputation[npc.faction]||0)<=-40&&act!=='fight')return notify(npc.name+': разговор окончен. Сначала восстанови отношение группировки.');if(act==='quest'){state.mode='quests';emit();return;}if(act==='news'){action('news');return;}if(act==='talk'){const definition=W.events.find(event=>event.id==='npc_story_'+id);if(!definition)return notify('Собеседник сейчас не готов разговаривать.');const key='npc-met:'+id,met=Boolean(state.npcMemory[id]?.visits)||state.knowledge.includes(key);state.npcMemory[id]={visits:(state.npcMemory[id]?.visits||0)+1,lastSeen:state.worldClock};if(!met)state.knowledge.push(key);startEvent(definition,'event');if(met){state.event.text=npc.name+' узнаёт тебя и кивает: «Снова ты. Помню нашу прошлую встречу». ';state.event.flow.history.push({text:npc.greeting,choice:'Вы уже встречались'});}emit();}}
  function turnIn(id){const q=state.quests.active.find(x=>x.id===id);if(!q)return;const d=W.quests.find(x=>x.id===id);if(!W.locations[state.player.location].npcs.includes(d.giver))return notify(`Найди заказчика: ${W.people[d.giver].name}.`);if(d.type==='deliver'&&count(d.item)<(d.count||1))return notify(`Нужно принести: ${I.items[d.item].name} ×${d.count||1}.`);if(d.type==='deliverType'&&!state.inventory.some(x=>I.items[x.id].type===d.itemType))return notify('В рюкзаке нет нужного артефакта.');if(!questReady(id))return notify('Условия поручения ещё не выполнены.');if(d.type==='deliver')remove(d.item,d.count||1);if(d.type==='deliverType'){const art=state.inventory.find(x=>I.items[x.id].type===d.itemType);removeItem(art.instanceId||art.id,1);}if(['kill','explore'].includes(d.type)&&q.progress<(d.count||1))return notify(`Пока выполнено ${q.progress}/${d.count}.`);if(d.type==='route'&&state.player.location!==d.returnTo)return notify('Вернись в сектор «'+W.locations[d.returnTo].name+'».');completeQuest(q);emit();return true;}
  function showEventChoice(i){chooseEvent(i);}
  function getMap(){return Object.entries(W.locations).map(([id,l])=>({id,name:l.name,danger:l.danger,known:state.known.includes(id),visited:state.visited.includes(id),current:id===state.player.location,open:unlocked(id),neighbors:l.neighbors}));}
  function questReady(id){const q=state.quests.active.find(q=>q.id===id),d=W.quests.find(d=>d.id===id);if(!q||!d)return false;if(d.type==='visit')return state.visited.includes(d.target);if(d.type==='route')return q.step>=1&&state.player.location===d.returnTo;if(d.type==='deliver')return count(d.item)>=(d.count||1);if(d.type==='deliverType')return state.inventory.some(x=>I.items[x.id]?.type===d.itemType);if(['kill','explore','research'].includes(d.type))return q.progress>=(d.count||1);return false;}
  function getQuests(){return {active:state.quests.active.map(q=>{const d=W.quests.find(d=>d.id===q.id),ready=questReady(q.id),automatic=['route','visit'].includes(d.type),progress=d.type==='deliver'?Math.min(d.count||1,count(d.item)):d.type==='deliverType'?Math.min(d.count||1,state.inventory.filter(x=>I.items[x.id]?.type===d.itemType).reduce((n,x)=>n+x.qty,0)):q.progress;return {...d,...q,progress,ready,automatic,status:ready?'Готово к сдаче':progress>0||q.step>0?'Выполняется':'Не выполнено',canTurnIn:ready&&!automatic&&W.locations[state.player.location].npcs.includes(d.giver)};}),available:questOffers(),completed:state.quests.completed.map(id=>({...W.quests.find(q=>q.id===id),status:'Выполнено'}))};}
  const invalidShopItems=new Set();
  function getShop(){const who=trader();if(!who)return null;let stock=['electrolyte','ration7','fieldSerum','probe7','radioBattery','bandage','antirad','canned','water','energy','ammo918','ammo919','ammo545','ammo762','ammo1270','ammo9x39'];if(state.player.location==='cordon')stock.push('pm','pistol19','aps','huntingRifle','jacket','leather','knife','sawedoff','fieldPack','gasmask','echoDetector','jellyfish');if(state.player.location==='agro'||state.player.location==='yantar')stock.push('stalkerSuit','aksu','shotgun','electronics','tools','milPack','sealedHelmet','spark','shell','svarog','fireball','moonlight','battery');if(state.player.location==='warehouses')stock.push('ak','armySuit','exoskeleton','vintar','vest','milPack','sealedHelmet','nightstar','gravi','ppVityaz');if(['researchCamp','dutyFort','freeCamp'].includes(state.player.location))stock.push('carbine7','smg7','surveyPack','surveyMask');const fac=shopFactor(who.faction);return{name:who.name,faction:who.faction,stock:[...new Set(stock)].filter(id=>{const item=I.items[id];if(item&&Number.isFinite(item.price)&&item.price>=0)return true;const key=state.player.location+':'+id;if(!invalidShopItems.has(key)){invalidShopItems.add(key);console.warn('[ZoneRPG] Пропущена недопустимая позиция магазина',{location:state.player.location,trader:who.name,itemId:id});}return false;}).map(id=>({id,item:I.items[id],price:Math.ceil(I.items[id].price*fac)}))};}
  function die(){if(state.expedition.active)state.lastExpedition=clone(state.expedition);resetExploration();state.travelTo=null;state.player.health=0;state.mode='dead';state.deathSummary={trips:state.player.trips,kills:state.statistics.kills,artifacts:state.statistics.artifacts,earnings:state.statistics.earnings,quests:state.statistics.quests};state.combat=null;state.event=null;log('Ты погиб в Зоне. Последнее сохранение осталось нетронутым.');emit('death');}
  function loadSavedGame(){const saved=window.ZoneRPGSave.read();if(!saved.ok){state.loadError=saved.reason==='corrupt'?'Сохранение повреждено. Его данные сохранены; можно начать новую игру или попробовать другую копию.':saved.reason==='empty'?'Сохранение отсутствует.':'Версия сохранения не поддерживается.';notify(state.loadError);return;}let restored;try{restored=S.sanitize(saved.data,I.items,W);}catch(error){console.error('[ZoneRPG] Не удалось восстановить сохранение',error);state.loadError='Не удалось восстановить сохранение. Исходная запись не изменена.';notify(state.loadError);return;}state=restored;state.loadError=null;if(state.travelTo&&!state.event&&!state.combat)arrive(state.travelTo);notify('Сохранение загружено.');}
  let lastCriticalAction='',lastCriticalAt=0;function action(name,value,extra){if(['event','eventReturn','attack','reload','buy','sell','drop','equipGear','unequipSlot','artifact','acceptQuest','turnIn','combatUse'].includes(name)){const key=name+':'+String(value??'');const now=performance.now();if(key===lastCriticalAction&&now-lastCriticalAt<180)return;lastCriticalAction=key;lastCriticalAt=now;}switch(name){case'researchQuest':{if(state.event||state.combat)break;const q=W.quests.find(x=>x.id===value);if(q?.type!=='research'||q.target!==state.player.location||!state.quests.active.some(x=>x.id===value)||questReady(value))break;startEvent(W.events.find(x=>x.id==='v7_research_'+q.giver),'event');emit();break;}case'joinFaction':joinFaction(value);break;case'leaveFaction':leaveFaction();break;case'travel':travel(value);break;case'investAttribute':investAttribute(value);break;case'explore':if(state.expedition.active)notify('Вылазка уже начата. Продолжите текущую встречу или вернитесь.');else explore();break;case'event':chooseEvent(Number(value));break;case'eventReturn':returnFromEvent();break;case'attack':attack();break;case'aim':aim();break;case'reload':reload(value);break;case'news':{if(state.event||state.combat)break;state.mode='event';state.event={id:'arrival_news_'+state.player.trips,category:'Слухи и новости',text:'У костра разговоры тише обычного. Кто-то всё же готов поделиться тем, что слышал в дороге.',choices:[{label:'Послушать новости',effects:{newsRoll:true},finish:true,resultText:'Ты записал главное в журнал КПК.'},{label:'Поблагодарить и уйти',finish:true,resultText:'Ты возвращаешься к дороге.'}],flow:{version:1,stageId:'news',stageIndex:0,phase:'choices',origin:'event',chain:[],visitedStages:['news'],claimedActions:[],flags:{},pending:null,resultText:'',lastChoice:''}};emit();break;}case'notebook':state.mode='notebook';emit();break;case'flee':flee();break;case'combatUse':combatUse(value);if(state.mode==='combatItems'&&state.combat)state.mode='combat';break;case'use':useItem(Number(value));break;case'equipGear':equipGear(value);break;case'equipWeapon':equipWeapon(value);break;case'equipArmor':equipArmor(value);break;case'unequipSlot':unequipSlot(value);break;case'switchWeapon':switchWeapon(value);break;case'artifact':toggleArtifact(value);break;case'drop':drop(value);break;case'buy':buy(value,Number(extra||1));break;case'sell':sell(value,Number(extra||1));break;case'breath':breath();break;case'rest':rest();break;case'npcAction':npcAction(value);break;case'acceptQuest':acceptQuest(value);break;case'turnIn':turnIn(value);break;case'mainMenu':state.mode='menu';emit();break;case'setSetting':state.settings[value.key]=value.value;if(value.key==='music')window.ZoneRPGAudio?.setMusic(Boolean(value.value));if(value.key==='sfx')window.ZoneRPGAudio?.setSfx(Boolean(value.value));emit();break;case'newGame':state.panelReturn='menu';state.mode='background';emit();break;case'startGame':if(!S.BACKGROUNDS[value])break;state=S.fresh(value);state.mode='play';notify('Начало пути: '+W.locations[state.player.location].name+' · '+S.BACKGROUNDS[value].name+'.');setAmbientEvent();emit();break;case'load':loadSavedGame();break;case'save':{const r=window.ZoneRPGSave.write(state);notify(r.ok?'Сохранение записано.':r.reason==='quota'?'В браузере недостаточно места для сохранения.':'Не удалось записать сохранение в этом браузере.');break;}case'deletePrompt':state.mode='deleteConfirm';emit();break;case'deleteSave':if(window.ZoneRPGSave.remove()){state.mode='settings';notify('Локальное сохранение удалено.');}else notify('Не удалось удалить сохранение.');break;case'settings':state.mode='settings';emit();break;case'closePanel':state.mode=state.panelReturn==='menu'?'menu':state.event&&!state.combat?'event':state.combat?'combat':'play';state.panelReturn=null;emit();break;case'resume':state.mode=state.combat?'combat':state.event?'event':'play';state.panelReturn=null;emit();break;case'continue':if(state.combat){state.mode='combat';emit();}else if(state.event){state.mode='event';emit();}else{state.mode='play';emit();}break;case'dismissEvent':if(state.event?.id.startsWith('arrival_')){state.event=null;state.mode='play';emit();}break;case'openPanel':if(!['settings','inventory','map','quests','character','trade','people','combatItems','combatWeapons','notebook','more','pause','factions','encyclopedia','expeditionReport','deleteConfirm'].includes(state.mode))state.panelReturn=state.mode;state.mode=value;emit();break;case'equipSlot':equipGear(value);break;default:break;}emit();}
  function getState(){const copy=clone(state),edges=W.mapEdges(),paths=edges.map(e=>[e.from,e.to]);const h=state.player.time;if(copy.event)copy.event.choices=copy.event.choices.filter(choiceAvailable);return {...copy,activity:state.combat?'combat':state.expedition.active?'expedition':state.travelTo?'worldTravel':'locationIdle',expeditionCost:X.cost(state.expedition.depth),enemyDefinitions:W.enemyTypes,eventDefinitions:W.events.map(e=>({id:e.id,category:e.category})),factionStatuses:Object.keys(W.factions).map(factionStatus),worldEventDefinitions:W.worldEvents,backgrounds:S.BACKGROUNDS,attributeInfo:S.ATTRIBUTE_INFO,masteryNames:S.MASTERY_NAMES,xpForNextLevel:xpForNextLevel(),items:I.items,weapons:I.weapons,activeWeapon:activeWeaponState(),locations:W.locations,people:W.people,factions:W.factions,map:getMap(),edgePaths:paths,mapEdges:edges,hasSave:window.ZoneRPGSave.has(),weight:weight(),capacity:capacity(),stats:finalStats(),passive:passive(),routes:getRoutes(),quests:getQuests(),shop:getShop(),radStage:state.player.radiation<20?'безопасно':state.player.radiation<50?'лёгкое облучение':state.player.radiation<80?'опасный уровень':'критическое состояние',timeLabel:h<5||h>=21?'Ночь':h<10?'Утро':h<17?'День':'Вечер'};}
  window.ZoneRPGEngine={getState,action,onChange(fn){listeners.add(fn);},hasSave:()=>window.ZoneRPGSave.has(),eventChance,getItemWeight:weight};
})();
